-- Rubric version 2, generated by scripts/build-rubric-sql.ts from the approved draft.
-- Run in the Supabase SQL editor. Safe to rerun while the version is a draft: it replaces
-- the competencies. Once published, nothing here changes anything.

insert into rubric_versions (version, notes) values (2, $q$Results count, Achievement, Analytical, captains (2026-10-16)$q$) on conflict (version) do nothing;

delete from rubric_competencies where rubric_version_id in (select id from rubric_versions where version = 2 and published_at is null);

insert into rubric_competencies
  (rubric_version_id, key, label, definition, strong_evidence, moderate_evidence, not_evidence, examples)
select id, 'leadership', $q$Leadership$q$, $q$The ability to see a problem and determine the best way forward and then being able to express the plan to subordinates and management. Good leadership is defined by the ability to inspire, guide, empower and then communicate a shared goal.$q$, $q$The ability to see the team as a whole and step in to set standards without being given specific authority, with a specific, observable result: for example, improved performance, a measurable change in team habits, or a goal the team reached. Being elected or selected captain also counts as Strong when the athlete describes what they did as captain or a result it produced.$q$, $q$Showed initiative after someone else set the goals and standards. Or stepped in to set standards without authority, but without a specific, observable result. Or was elected or selected captain by teammates or coaches, even without further detail: captains are chosen for showing they are among the best and a leader.$q$, $q$I was put in charge and my teammates followed me. Saying "I'm a natural leader." Being the loudest voice. Taking credit for the team's results without naming your own actions.$q$, $j$[{"story":"During a midseason slump, our team was struggling with confidence. I organized extra film sessions, kept energy high in practice, and made sure younger players felt supported. We turned the momentum around and finished the season strong with 3 wins in our final 4 games.","rating":"strong","why":"Organized sessions without the prompting of coaches. Understood the importance of setting an example for younger players. Then gave a specific example of increase in performance."},{"story":"I made it a point to be the first one in the gym and encouraged my teammates to do the same. I established specialized workouts for each position and encouraged each position to have a position leader. Over time, teammates started joining me, and it raised the overall work ethic of the group.","rating":"moderate","why":"Recognized the need to set the example so others would follow. Establishing position leads shows they did not need to be \"in charge.\" Specific examples of performance would have been better than simply stating \"raised the work ethic of the group.\""},{"story":"My teammates voted me captain as a sophomore, the first sophomore captain in our program in ten years.","rating":"moderate","why":"Teammates chose them as captain, which shows they earned the team's trust as one of its best and a leader. Describing what they did as captain, and what changed, would make it Strong."}]$j$::jsonb
from rubric_versions where version = 2 and published_at is null;

insert into rubric_competencies
  (rubric_version_id, key, label, definition, strong_evidence, moderate_evidence, not_evidence, examples)
select id, 'discipline', $q$Discipline$q$, $q$Keeps commitments and maintains reliable habits over time. A manager sees consistent preparation, follow-through, and responsible management of competing demands.$q$, $q$Describes a repeatable routine across a season or another meaningful period, with concrete frequency or milestones, and a result the routine produced: for example, sessions completed against the plan, a measured improvement, or a goal reached. Tracking commitments or managing competing demands with limited reminders makes the evidence stronger.$q$, $q$Completes a defined routine over a shorter period or relies on reminders. Gives specific evidence of follow-through, but independent management or consistency over time is limited. Or describes a sustained routine but no result it produced.$q$, $q$Calling oneself dedicated. Simply being on a team or attending required activities without detail. One intense workout, extreme training volume, or ignoring recovery guidance.$q$, $j$[{"story":"For our 16-week season, I scheduled four weekly training sessions and two study blocks around classes and travel. I logged each session and moved study blocks before away games. I completed 60 of 64 sessions; the other four were rest days agreed with our trainer.","rating":"strong","why":"Shows a sustained routine, tracking, and independent scheduling. Agreed recovery days do not weaken responsible follow-through."},{"story":"For three preseason weeks, I completed all three weekly lifting sessions. Our coach sent reminders before each session, and I checked off the workouts afterward.","rating":"moderate","why":"Specific, repeated follow-through is present, but the period is short and reminders support adherence."}]$j$::jsonb
from rubric_versions where version = 2 and published_at is null;

insert into rubric_competencies
  (rubric_version_id, key, label, definition, strong_evidence, moderate_evidence, not_evidence, examples)
select id, 'resilience', $q$Resilience$q$, $q$Responds constructively after disappointment, failure, or disruption. A manager sees someone who seeks support when needed, takes useful next steps, and rebuilds progress.$q$, $q$Names a meaningful setback and describes constructive actions afterward. Sustains those actions through difficulty or further disappointment and shows restored participation, progress, or a workable new direction. Returning to a previous performance level is not required.$q$, $q$Describes a setback and at least one constructive response. Recovery is early, follow-through is brief, or progress is not yet clear.$q$, $q$Experiencing injury or hardship without describing a response. Saying "I never give up." Winning after a loss without explaining actions. Playing through injury against medical advice.$q$, $j$[{"story":"After an ankle injury ended my season, I followed the trainer's recovery plan for 12 weeks and kept a weekly progress log. When a reassessment delayed running, I asked for safe alternatives and continued approved work. I later returned to modified team practice with clearance.","rating":"strong","why":"Describes sustained constructive action, response to a further setback, and a concrete recovery milestone within medical guidance."},{"story":"After I missed the qualifying standard, I met with my coach to review the race and completed the next week of planned practices. I have not raced again yet.","rating":"moderate","why":"Shows a constructive initial response to disappointment; sustained rebuilding and later progress are not yet described."}]$j$::jsonb
from rubric_versions where version = 2 and published_at is null;

insert into rubric_competencies
  (rubric_version_id, key, label, definition, strong_evidence, moderate_evidence, not_evidence, examples)
select id, 'adaptability', $q$Adaptability$q$, $q$Adjusts methods when conditions, roles, or information change. A manager sees someone who learns, tests a different approach, and uses feedback to improve it.$q$, $q$Identifies a change or evidence that the old approach was ineffective. Explains a specific adjustment, applies it, and checks how it worked. Reports a specific result in the new conditions: for example, fewer errors, a faster time, or a new role performed well.$q$, $q$Makes a concrete adjustment to a new role or instruction, but testing, refinement, or effectiveness is limited. Following a suggested change can count when actual application is described.$q$, $q$A new coach, role, or system without describing changed behavior. Saying "I am flexible." Continuing the same approach after a setback. Obeying instructions without evidence of learning or application.$q$, $j$[{"story":"When our team changed defensive systems, I initially missed rotation assignments. I reviewed clips with our coach, built a cue sheet, and practiced the rotations with a teammate. Over four games, my missed assignments fell from six to one per game, and I updated the cues for the coverage I still missed.","rating":"strong","why":"Identifies a changed demand, applies a new learning method, checks results, and refines the response."},{"story":"When our coach moved me to a new position, I practiced its footwork for two sessions and used the new steps in a scrimmage. I have not reviewed how well I performed yet.","rating":"moderate","why":"A specific adjustment was applied, but effectiveness and refinement remain unknown."}]$j$::jsonb
from rubric_versions where version = 2 and published_at is null;

insert into rubric_competencies
  (rubric_version_id, key, label, definition, strong_evidence, moderate_evidence, not_evidence, examples)
select id, 'communication', $q$Communication$q$, $q$Listens, shares useful information clearly, and checks that people understand one another. A manager sees fewer misunderstandings and clearer expectations or handoffs.$q$, $q$Describes a communication need, listens to others, and adapts the message or channel to the audience. Checks understanding and shows a concrete result such as corrected confusion, agreed responsibilities, or a reliable handoff. A single complex interaction can qualify.$q$, $q$Shares relevant information or listens and clarifies in a straightforward situation. Audience adaptation, confirmation of understanding, or the resulting alignment is limited.$q$, $q$Being outgoing, popular, loud, or a frequent speaker. Saying "I am a good communicator." Sending messages without describing their content or purpose. Polished wording alone.$q$, $j$[{"story":"New teammates were using different names for the same defensive calls. I asked each group which terms they used, worked with the coach to agree on one set, and made a short reference sheet. I asked players to explain each call back during practice. By the next scrimmage, everyone used the agreed terms and we had no call-related mix-ups.","rating":"strong","why":"Listens, tailors a shared reference, confirms understanding, and describes resolved confusion."},{"story":"Before an away meet, I posted the coach's departure time and packing list in our team chat. One teammate asked which entrance to use, so I checked with the coach and replied.","rating":"moderate","why":"Gives useful information and resolves one question, but broader understanding and alignment are not established."}]$j$::jsonb
from rubric_versions where version = 2 and published_at is null;

insert into rubric_competencies
  (rubric_version_id, key, label, definition, strong_evidence, moderate_evidence, not_evidence, examples)
select id, 'execution', $q$Execution$q$, $q$Turns a goal into completed work that meets agreed requirements. A manager sees someone who plans tasks, manages dependencies, resolves obstacles, and delivers a usable result.$q$, $q$Defines a deliverable and success criteria, organizes the work, and owns follow-through. Coordinates dependencies or resolves an obstacle. Completes the deliverable and checks it against the deadline, scope, quality, or other agreed requirements.$q$, $q$Completes a bounded assigned task with a concrete result, but planning and ownership are limited. A larger project still in progress may show Moderate evidence when meaningful completed milestones are specified.$q$, $q$Ideas, goals, or plans with no completed work. Effort or attendance alone. Claiming a win or the team's result without naming your own part. Personal athletic results such as records and personal bests belong under Achievement.$q$, $j$[{"story":"I owned logistics for a team clinic with a goal of serving 40 local students. I built the schedule, confirmed the gym and volunteers, and tracked registrations. When two volunteers canceled, I reassigned stations and shortened transitions. We ran the clinic on the planned date for 43 students, completed every station, and stayed within our $300 budget.","rating":"strong","why":"Shows planning, ownership, obstacle resolution, and a completed deliverable checked against scope, timing, and budget."},{"story":"For our team clinic, the coach asked me to prepare 30 equipment kits using a checklist. I assembled and checked all 30 before the deadline and handed them to the event lead.","rating":"moderate","why":"Delivers a specific assigned output on time, with limited evidence of broader planning or dependency management."}]$j$::jsonb
from rubric_versions where version = 2 and published_at is null;

insert into rubric_competencies
  (rubric_version_id, key, label, definition, strong_evidence, moderate_evidence, not_evidence, examples)
select id, 'achievement', $q$Achievement$q$, $q$Sets a clear goal or standard, prepares for it, and reaches or beats it when it counts. A manager sees someone who hits targets, measures progress, and delivers under pressure.$q$, $q$Names a goal, standard, or competition, describes the preparation behind it, and reports a specific result the athlete personally achieved that met or beat it: for example, a personal best, a record, a ranking, a qualifying mark, or a win where the athlete names their own part. Results under real competition pressure count fully, and a single event qualifies when the preparation behind it is described.$q$, $q$Reports a specific personal result, but the goal or the preparation behind it is not described. Or describes preparation and measured progress toward a goal that has not been reached yet.$q$, $q$The team's result without the athlete's own part. Effort, hours, or attendance with no result. Saying "I'm a winner" or "I'm competitive." Results from events the athlete did not take part in.$q$, $j$[{"story":"My goal was to break 4:20 in the 1500 by the conference meet. Starting in January I added two tempo runs a week and wrote down my splits after each one. At conference I ran 4:17.6, a personal best by three seconds, and placed fourth to score points for our team.","rating":"strong","why":"A clear goal, preparation that was tracked, and a measured personal result that beat the goal at a championship meet."},{"story":"I scored a career-high 22 points in our rivalry game in front of a sold-out crowd.","rating":"moderate","why":"A specific personal result under pressure, but no goal or preparation is described."},{"story":"I set a goal to raise my free-throw percentage from 68% to 80% this season. I shoot 100 extra free throws after every practice, and I'm at 74% through 12 games.","rating":"moderate","why":"Real preparation and measured progress, but the goal has not been reached yet."}]$j$::jsonb
from rubric_versions where version = 2 and published_at is null;

insert into rubric_competencies
  (rubric_version_id, key, label, definition, strong_evidence, moderate_evidence, not_evidence, examples)
select id, 'analytical', $q$Analytical$q$, $q$Uses data, observation, or careful reasoning to understand a problem and choose what to do. A manager sees someone who gathers the right information, finds the pattern or cause, and makes decisions backed by evidence.$q$, $q$Describes a question or problem, gathers specific information (stats, video, measurements, records), finds a pattern or cause, and uses it to choose an action. Reports a result that shows the analysis worked.$q$, $q$Gathers or tracks specific information and draws a reasonable conclusion, but does not act on it or does not report what changed. Or applies someone else's analysis with care and describes how.$q$, $q$Saying "I'm analytical" or "I have a high game IQ." Tracking numbers without using them. Watching film without a finding. Decisions made on a hunch with no information.$q$, $j$[{"story":"We kept losing points late in sets. I went through the stats from our last eight matches and found most of our errors came on serve receive right after timeouts. I suggested a two-minute receive drill coming out of every timeout in practice. Over the next six matches, our serve-receive errors after timeouts dropped from five to two per match.","rating":"strong","why":"A clear question, data gathered, a pattern found, an action chosen from it, and a measured result."},{"story":"I kept a spreadsheet of every round I played this fall: fairways hit, greens in regulation, and putts. It showed that most of my lost strokes came from putts inside ten feet.","rating":"moderate","why":"Gathered specific data and found a clear pattern, but no action or result is described yet."}]$j$::jsonb
from rubric_versions where version = 2 and published_at is null;

-- Check: expect 8 rows.
select key, label from rubric_competencies where rubric_version_id = (select id from rubric_versions where version = 2);
